-- 9003_Master_Rebuild.sql
-- Full from-scratch rebuild -- every table, view, seed row, and RLS
-- policy in one file, in correct dependency order. Covers all 16
-- tables (the original 8, the 5-table Attendance module, the 2
-- attachment tables, and Quick Log) plus their 2 Storage buckets, and
-- all 12 views. Generated by literal concatenation of the individual
-- verified source files, not hand-assembled from memory -- regenerate
-- this file fresh whenever those source files change, rather than
-- hand-patching it directly.
--
-- Regenerated this pass specifically to add:
--   - quicklog_entries (1160) -- flat, standalone, no foreign keys
--   - its RLS policy and RLS enabled (no Storage bucket needed --
--     Quick Log's inline images are base64, not Storage-backed)
--   - its seed data (3140) -- 118 real historical entries migrated
--     from the old Notepad .LOG file, created_at correctly written
--     with an explicit +05:30 (Asia/Kolkata) offset so these convert
--     to true UTC rather than being misread as already-UTC
--
-- Earlier passes (todo_attachments/update_prep_attachments and their
-- buckets/policies; personal_profile.short_name position;
-- attendance_log.oracle_updated default) are still included below,
-- unchanged.
--
-- Run this top-to-bottom on a genuinely empty database to stand up a
-- complete copy of PWMS AC's schema, Attendance module, attachment
-- tables/buckets, and Quick Log included. Load your data export
-- separately afterward.
--
-- 9010_Attendance_Master_Rebuild.sql is retired now that this file
-- covers everything -- safe to delete.

-- ==========================================================================
-- SOURCE: 1010_Create_Portfolio.sql
-- ==========================================================================
-- 1010_Create_Portfolio.sql

create table if not exists portfolio (

    portfolio_id uuid
        primary key
        default gen_random_uuid(),

    portfolio_name text
        not null,

    portfolio_type text
        not null,

    description text,

    enabled boolean
        not null
        default true,

    display_order integer
        default 100,

    created_at timestamptz
        not null
        default now(),

    created_by text
        not null
        default 'System',

    updated_at timestamptz
        not null
        default now(),

    updated_by text
        not null
        default 'System'
);

create unique index if not exists
uq_portfolio_name
on portfolio(portfolio_name);

create index if not exists
idx_portfolio_name
on portfolio(portfolio_name);

create index if not exists
idx_portfolio_enabled
on portfolio(enabled);

grant all on table portfolio to anon;
grant all on table portfolio to authenticated;


