-- SOURCE: 1140_Create_TodoAttachments.sql
-- ==========================================================================
-- 1140_Create_TodoAttachments.sql
-- One row per uploaded file, many rows per ToDo. Cascades on ToDo
-- delete, since an attachment has no value once orphaned from the
-- ToDo it supports.
--
-- storage_path points into the "todo-attachments" Supabase Storage
-- bucket, not this database — the bucket itself is created in the
-- RLS/Storage section below, not here.

create table if not exists todo_attachments (

    attachment_id uuid
        primary key
        default gen_random_uuid(),

    todo_id uuid
        not null
        references todo(todo_id)
        on delete cascade,

    file_name text
        not null,

    storage_path text
        not null,

    file_size bigint,

    label text,

    uploaded_at timestamptz
        not null
        default now(),

    uploaded_by text
);

create index if not exists
idx_todo_attachments_todo
on todo_attachments(todo_id);

grant all on table todo_attachments to anon;
grant all on table todo_attachments to authenticated;


