-- ==========================================================================
-- SOURCE: 1150_Create_UpdatePrepAttachments.sql
-- ==========================================================================
-- 1150_Create_UpdatePrepAttachments.sql
-- Genuinely one row per update_prep_history row — a single screenshot
-- of the written update as actually sent, per period+format. The
-- UNIQUE constraint on history_id enforces that at the database
-- level. Cascades on update_prep_history delete, same reasoning as
-- todo_attachments.
--
-- storage_path points into the "updateprep-attachments" Supabase
-- Storage bucket — created in the RLS/Storage section below.

create table if not exists update_prep_attachments (

    attachment_id uuid
        primary key
        default gen_random_uuid(),

    history_id uuid
        not null
        unique
        references update_prep_history(history_id)
        on delete cascade,

    file_name text
        not null,

    storage_path text
        not null,

    file_size bigint,

    label text,

    uploaded_at timestamptz
        not null
        default now(),

    uploaded_by text
);

grant all on table update_prep_attachments to anon;
grant all on table update_prep_attachments to authenticated;


