-- ==========================================================================
-- SOURCE: 1130_Create_AttendanceLog.sql
-- ==========================================================================
-- 1130_Create_AttendanceLog.sql
-- One row per day, log_date itself as the primary key — duplicate
-- entries for the same day are impossible by construction, not by
-- application-level checking.
--
-- Regenerated from the verified live 9002 snapshot, not patched.
--
-- Three text fields serve three different, deliberately separate jobs:
--   reason           — yours, freely editable any time
--   description      — frozen copy of attendance_codes.attendance_type
--                       at the moment this was logged, never re-read
--                       or recalculated afterward
--   hr_type_frozen   — frozen copy of attendance_codes.hr_type,
--                       same reasoning
-- Both frozen fields exist so a future redefinition of what a code
-- means can never silently rewrite what an old entry meant when it
-- was actually logged.

create table if not exists attendance_log (

    log_date date
        primary key,

    code text
        not null
        references attendance_codes(code),

    reason text,

    description text,
    -- frozen at insert, not a live join

    hr_type_frozen text,
    -- frozen at insert, not a live join

    oracle_updated boolean
        default true,
    -- renamed from the old SAMAY flag — same purpose, tracks the
    -- current HRIS system (Oracle), not SAMAY specifically. Defaults
    -- true since it rarely fires in practice — the app always sends
    -- an explicit value (checkbox state, or hardcoded true for bulk
    -- weekend fill); this default only matters as a fallback for
    -- anything inserted outside the app's own code paths.

    created_at timestamptz
        not null
        default now(),

    updated_at timestamptz
        not null
        default now(),


    log_start_time time
        without time zone null
        default '08:30:00',

    log_end_time time
        without time zone null
        default '17:00:00'


);

create index if not exists
idx_attendance_log_code
on attendance_log(code);

grant all on table attendance_log to anon;
grant all on table attendance_log to authenticated;


-- ==========================================================================
-- SOURCE: 1160_Create_QuickLogEntries.sql
-- ==========================================================================
-- 1160_Create_QuickLogEntries.sql
-- Quick Log — a free-form scribbler, translating the Notepad ".LOG"
-- habit (open, get a timestamp, type anything, save) into real rows
-- instead of one ever-growing text file. Newest-first in the UI, by
-- created_at descending.
--
-- No foreign keys -- intentionally flat and standalone, not tied to
-- a Portfolio/Project/Milestone/Activity the way task_log is.

create table if not exists quicklog_entries (

    entry_id uuid
        primary key
        default gen_random_uuid(),

    entry_text text
        not null,
    -- Stores HTML, not plain text -- the rich-text box (bold/italic/
    -- underline/lists, pasted tables, inline base64 images) writes
    -- real markup here. Historical entries migrated from the old
    -- Notepad .LOG file carry their date baked in as a leading
    -- "DD-Mon-YYYY HH:MM" line, HTML-escaped, matching how the app
    -- auto-fills new entries -- so old and new look identical.

    created_at timestamptz
        not null
        default now(),

    created_by text,

    updated_at timestamptz
        not null
        default now(),

    updated_by text
);

create index if not exists
idx_quicklog_entries_created_at
on quicklog_entries(created_at desc);

grant all on table quicklog_entries to anon;
grant all on table quicklog_entries to authenticated;


-- ==========================================================================
-- SOURCE: 2030_View_MilestoneDetails.sql
-- ==========================================================================
-- 2030_View_MilestoneDetails.sql

drop view if exists vw_milestone_details;

create view vw_milestone_details as

select

    m.milestone_id,
    m.project_id,
    p.portfolio_id,

    m.milestone_code,
    m.milestone_name,

    p.project_code,
    p.project_name,

    pf.portfolio_name,
    pf.portfolio_type,

    m.description,

    m.start_date,
    m.target_date,

    m.status,
    m.enabled,

    m.created_at,
    m.created_by,

    m.updated_at,
    m.updated_by

from milestone m

inner join project p
    on p.project_id = m.project_id

inner join portfolio pf
    on pf.portfolio_id = p.portfolio_id;

grant select on vw_milestone_details to anon;
grant select on vw_milestone_details to authenticated;


-- ==========================================================================
-- SOURCE: 2040_View_ActivityDetails.sql
-- ==========================================================================
-- 2040_View_ActivityDetails.sql

drop view if exists vw_activity_details;

create view vw_activity_details as

select

    a.activity_id,
    a.activity_name,
    a.description,
    a.target_date,
    a.priority,
    a.status,
    a.display_order,
    a.enabled,

    a.created_at,
    a.created_by,

    a.updated_at,
    a.updated_by,

    a.milestone_id,

    m.milestone_name,

    m.project_id,
    m.project_name,

    m.portfolio_id,
    m.portfolio_name

from activity a

left join vw_milestone_details m
    on m.milestone_id = a.milestone_id;

grant select on vw_activity_details to anon;
grant select on vw_activity_details to authenticated;


-- ==========================================================================
-- SOURCE: 2041_View_ReviewOpenActivities.sql
-- ==========================================================================
-- 2041_View_ReviewOpenActivities.sql

drop view if exists vw_review_open_activities;

create view vw_review_open_activities as

select

    activity_id,
    activity_name,
    status,
    target_date,
    portfolio_name,
    project_name,
    milestone_name,
    enabled

from vw_activity_details

where
    enabled = true
    and status not in ('Completed', 'Cancelled');

grant select on vw_review_open_activities to anon;
grant select on vw_review_open_activities to authenticated;


-- ==========================================================================
-- SOURCE: 2042_View_ReviewActivitySummary.sql
-- ==========================================================================
-- 2042_View_ReviewActivitySummary.sql

drop view if exists vw_review_activity_summary;

create view vw_review_activity_summary as

select

    count(*) filter (
        where enabled = true
        and status not in ('Completed', 'Cancelled')
    ) as open_activities,

    count(*) filter (
        where enabled = true
        and status = 'In Progress'
    ) as in_progress_activities,

    count(*) filter (
        where enabled = true
        and status = 'Completed'
        and updated_at >= date_trunc('week', current_date)
    ) as completed_activities,

    count(*) filter (
        where enabled = true
        and status not in ('Completed', 'Cancelled')
        and target_date < current_date
    ) as overdue_activities

from activity;

grant select on vw_review_activity_summary to anon;
grant select on vw_review_activity_summary to authenticated;


-- ==========================================================================
-- SOURCE: 2050_View_Todo.sql
-- ==========================================================================
-- 2050_View_Todo.sql

drop view if exists vw_todo;

create view vw_todo as

select

    t.todo_id,
    t.todo_text,
    t.notes,
    t.status,
    t.due_date,
    t.display_order,
    t.enabled,

    t.created_at,
    t.created_by,

    t.updated_at,
    t.updated_by,

    t.milestone_id,

    m.milestone_name,

    p.project_id,
    p.project_name,

    pf.portfolio_id,
    pf.portfolio_name

from todo t

left join milestone m
    on t.milestone_id = m.milestone_id

left join project p
    on m.project_id = p.project_id

left join portfolio pf
    on p.portfolio_id = pf.portfolio_id

where t.enabled = true;

grant all on table vw_todo to anon;
grant all on table vw_todo to authenticated;


-- ==========================================================================
-- SOURCE: 2060_View_TaskLogDetails.sql
-- ==========================================================================
-- 2060_View_TaskLogDetails.sql

drop view if exists vw_task_log_details;

create view vw_task_log_details as

select

    tl.task_log_id,
    tl.task_date,
    tl.task_description,
    tl.minutes_spent,
    tl.start_time,
    tl.end_time,
    tl.display_order,

    tl.created_at,
    tl.created_by,

    tl.updated_at,
    tl.updated_by,

    tl.todo_id,
    t.todo_text,

    tl.activity_id,
    a.activity_name,

    m.milestone_id,
    m.milestone_name,

    p.project_id,
    p.project_name

from task_log tl

left join todo t
    on tl.todo_id = t.todo_id

left join activity a
    on tl.activity_id = a.activity_id

left join milestone m
    on coalesce(t.milestone_id, a.milestone_id) = m.milestone_id

left join project p
    on m.project_id = p.project_id;

grant select on vw_task_log_details to anon;
grant select on vw_task_log_details to authenticated;


-- ==========================================================================
-- SOURCE: 2061_View_ReviewRecentLogs.sql
-- ==========================================================================
-- 2061_View_ReviewRecentLogs.sql

drop view if exists vw_review_recent_logs;

create view vw_review_recent_logs as

select *
from vw_task_log_details
order by task_date desc, start_time desc;

grant select on vw_review_recent_logs to anon;
grant select on vw_review_recent_logs to authenticated;


-- ==========================================================================
-- SOURCE: 2062_View_ReviewTimeSummary.sql
-- ==========================================================================
-- 2062_View_ReviewTimeSummary.sql

drop view if exists vw_review_time_summary;

create view vw_review_time_summary as

select

    coalesce(
        sum(
            case
                when task_date = current_date
                then minutes_spent
                else 0
            end
        ),
        0
    ) as today_minutes,

    coalesce(
        sum(
            case
                when task_date >= date_trunc('week', current_date)::date
                then minutes_spent
                else 0
            end
        ),
        0
    ) as week_minutes,

    coalesce(
        sum(
            case
                when task_date >= date_trunc('month', current_date)::date
                then minutes_spent
                else 0
            end
        ),
        0
    ) as month_minutes

from task_log;

grant select on vw_review_time_summary to anon;
grant select on vw_review_time_summary to authenticated;


-- ==========================================================================
-- SOURCE: 2071_View_ReviewPortfolioTime.sql
-- ==========================================================================
-- 2071_View_ReviewPortfolioTime.sql
-- NOTE: this view only joins task_log -> activity -> milestone. It has
-- no awareness of the newer task_log.todo_id path, so hours logged
-- against a ToDo (most current logging) are miscounted into
-- "Standalone Activities." Left exactly as-is per instruction, matching
-- live behavior precisely rather than silently correcting it here.

drop view if exists vw_review_portfolio_time;

create view vw_review_portfolio_time as

select

    coalesce(p.portfolio_name, 'Standalone Activities') as portfolio_name,

    round(sum(t.minutes_spent) / 60.0, 1) as hours_spent

from task_log t

left join activity a
    on t.activity_id = a.activity_id

left join milestone m
    on a.milestone_id = m.milestone_id

left join project pr
    on m.project_id = pr.project_id

left join portfolio p
    on pr.portfolio_id = p.portfolio_id

group by portfolio_name

order by hours_spent desc;

grant select on vw_review_portfolio_time to anon;
grant select on vw_review_portfolio_time to authenticated;


-- ==========================================================================
-- SOURCE: 2072_View_PayrollMonth.sql
-- ==========================================================================
-- 2072_View_PayrollMonth.sql
-- Cross-table report, not flavored by a single table — matches an
-- attendance_log row to whichever employment_history stint was active
-- on that date, then computes the payroll month/year using THAT
-- stint's own cycle days (not a single global rule), since a future
-- employer could run a different cycle entirely.
--
-- Rarely used — mainly relevant around a Last Working Day. Left as its
-- own separate view rather than folded into the everyday attendance
-- pages, per instruction.

drop view if exists vw_payroll_month;

create view vw_payroll_month as

select

    al.log_date,
    al.code,
    al.description,
    al.hr_type_frozen,

    eh.employer_name,
    eh.payroll_cycle_start_day,
    eh.payroll_cycle_end_day,

    case
        when extract(day from al.log_date) >= eh.payroll_cycle_start_day
        then case
                when extract(month from al.log_date) = 12 then 1
                else extract(month from al.log_date) + 1
             end
        else extract(month from al.log_date)
    end as payroll_month,

    case
        when extract(day from al.log_date) >= eh.payroll_cycle_start_day
             and extract(month from al.log_date) = 12
        then extract(year from al.log_date) + 1
        else extract(year from al.log_date)
    end as payroll_year

from attendance_log al

left join employment_history eh
    on al.log_date >= eh.start_date
    and (eh.end_date is null or al.log_date <= eh.end_date);

grant select on vw_payroll_month to anon;
grant select on vw_payroll_month to authenticated;


-- ==========================================================================
-- SOURCE: 2100_View_CurrentEmployment.sql
-- ==========================================================================
-- 2100_View_CurrentEmployment.sql
-- Convenience view — "give me my current job" without every page
-- needing to repeat the end_date IS NULL filter itself.

drop view if exists vw_current_employment;

create view vw_current_employment as

select *
from employment_history
where end_date is null
order by start_date desc
limit 1;

grant select on vw_current_employment to anon;
grant select on vw_current_employment to authenticated;


-- ==========================================================================
-- SOURCE: 2130_View_AttendanceLog.sql
-- ==========================================================================
-- 2130_View_AttendanceLog.sql
-- Plain ordered passthrough — kept consistent with the rest of the app's
-- convention of always reading through a view, even for a 1:1 relationship.

drop view if exists vw_attendance_log;

create view vw_attendance_log as

select *
from attendance_log
order by log_date desc;

grant select on vw_attendance_log to anon;
grant select on vw_attendance_log to authenticated;


